contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: params choose an amount to burn and an address to act as caller
    // msg.sender for calls to c will be this contract, which is the original deployer/owner of c
    function run(uint256 burnAmount, address other) public payable {
        require(other != address(0));
        // Read before values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalanceThis = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeBalanceOther = c.balanceOf(other); if (__ESBMC_reverted()) return;

        // attempt burn as owner (this contract is the owner because it deployed c)
        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBalanceThis = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterBalanceOther = c.balanceOf(other); if (__ESBMC_reverted()) return;

        // Rule: If burn succeeded then totalSupply and caller balance decreased by burnAmount,
        // and other balances unchanged. If burn reverted then none of these three observables changed.
        assert(
            (!reverted && afterTotal + burnAmount == beforeTotal && afterBalanceThis + burnAmount == beforeBalanceThis && afterBalanceOther == beforeBalanceOther)
            || (reverted && afterTotal == beforeTotal && afterBalanceThis == beforeBalanceThis && afterBalanceOther == beforeBalanceOther)
        );
    }

    receive() external payable {}
}

